// ส่งไฟล์แนบของอีเมล Timesheet เข้า OBS (ไม่อ่านเอง — คนกดอ่านในแท็บ "ดึงจาก Gmail" ของ OBS)
const ALLOWED = ['pdf', 'xlsx', 'xls', 'csv', 'jpg', 'jpeg', 'png', 'tif', 'tiff', 'webp'];
const IMAGES = ['jpg', 'jpeg', 'png', 'tif', 'tiff', 'webp'];
const MIN_IMAGE_BYTES = 40 * 1024;

function toIso(j) {
  if (j.date) return new Date(j.date).toISOString();
  if (j.internalDate) return new Date(Number(j.internalDate)).toISOString();
  return new Date().toISOString();
}

function fromText(j) {
  const raw = j.from ?? j.From ?? null;
  if (!raw) return null;
  if (typeof raw === 'string') return raw;
  return raw.text ?? null;
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const binary = items[i].binary ?? {};
  for (const key of Object.keys(binary)) {
    const fileName = binary[key].fileName ?? '';
    const m = fileName.toLowerCase().match(/\.([a-z0-9]+)$/);
    const ext = m ? m[1] : '';
    if (!ALLOWED.includes(ext)) continue;
    const file = await this.helpers.getBinaryDataBuffer(i, key);
    if (IMAGES.includes(ext) && file.length < MIN_IMAGE_BYTES) continue;
    out.push({
      json: {
        sourceEmailId: j.id,
        fileName: fileName,
        fileBase64: file.toString('base64'),
        subject: j.subject ?? j.Subject ?? '',
        from: fromText(j),
        bodyText: j.text ?? j.snippet ?? '',
        receivedAt: toIso(j),
      },
    });
  }
}
return out;
